content.content:
    # Complex numbers: compare the components separately.
    if _safe(lambda: bool(gold_value.is_real is False or target_value.is_real is False), False):
        as_complex = _safe(lambda: (complex(gold_value), complex(target_value)))
        if as_complex is None:
            return False
        a, b = as_complex
        tolerance = 10 ** (-float_rounding)
        return (
            abs(a.real - b.real) <= tolerance * 1.5
            and abs(a.imag - b.imag) <= tolerance * 1.5
        )

    rounded = _safe(
        lambda: gold_value.round(float_rounding) == target_value.round(float_rounding),
        False,
    )
    if rounded:
        return True

    # Rounding is brittle right on a .5 boundary, so also accept a plain
    # absolute/relative tolerance at the same scale.
    def _tolerant() -> bool:
        a = float(gold_value)
        b = float(target_value)
        tolerance = 10 ** (-float_rounding)
        return abs(a - b) <= tolerance * (1 + min(abs(a), abs(b)))

    return bool(_safe(_tolerant, False))


# ---------------------------------------------------------------------------
# Symbolic comparison
# ---------------------------------------------------------------------------


def sympy_symbolic_eq(gold: Any, target: Any) -> bool:
    """Try to prove ``gold - target == 0`` symbolically."""
    if _safe(lambda: bool(gold == target), False):
        return True

    difference = _safe(lambda: gold - target)
    if difference is None:
        return False

    for transform in (
        sympy.simplify,
        lambda e: sympy.simplify(sympy.expand(e)),
        lambda e: sympy.simplify(sympy.trigsimp(e)),
        lambda e: sympy.cancel(sympy.together(e)),
        lambda e: sympy.radsimp(sympy.simplify(e)),
    ):
        result = _safe(lambda: transform(difference))
        if result is not None and _safe(lambda: bool(result == 0), False):
            return True
    return False


def _expr_eq(
    gold: Any,
    target: Any,
    float_rounding: int,
    numeric_precision: int,
) -> bool:
    """Numeric-then-symbolic comparison of two scalar expressions."""
    if _safe(lambda: bool(gold == target), False):
        return True

    gold_symbols = getattr(gold, "free_symbols", set()) or set()
    target_symbols = getattr(target, "free_symbols", set()) or set()

    if not gold_symbols and not target_symbols:
        if sympy_numeric_eq(gold, target, float_rounding, numeric_precision):
            return True
        # Exact constants can still need symbolic work, e.g. nested radicals.
        return sympy_symbolic_eq(gold, target)

    # With free symbols on either side, numeric substitution is meaningless;
    # the symbols must line up and the difference must vanish identically.
    if gold_symbols != target_symbols:
        return False
    return sympy_symbolic_eq(gold, target)


# ---------------------------------------------------------------------------
# strict=False: compare up to a renaming of the free symbols
# ---------------------------------------------------------------------------


def _symbols_in_order(expr: Any) -> list[Symbol]:
    """Free symbols in order of first appearance (deterministic)."""
    seen: list[Symbol] = []

    def walk(node: Any) -> None:
        if isinstance(node, MatrixBase):
            for element in node:
                walk(element)
            return
        if isinstance(node, Symbol):
            if node not in seen:
                seen.append(node)
            return
        for arg in getattr(node, "args", ()) or ():
            walk(arg)

    walk(expr)
    return seen


def _rename(expr: Any, mapping: dict) -> Any:
    if isinstance(expr, MatrixBase):
        return expr.applyfunc(lambda e: e.subs(mapping, simultaneous=True))
    return expr.subs(mapping, simultaneous=True)


def _canonical_symbol_forms(expr: Any, limit: int = 6) -> Iterable[Any]:
    """Yield the expression with its free symbols renamed to placeholders.

    The first candidate maps symbols by order of appearance, which handles the
    common case in one shot.  If the two expressions order their symbols
    differently we fall back to trying every bijection, which is affordable
    because answers do not contain many distinct variables.
    """
    symbols = _symbols_in_order(expr)
    if not symbols:
        yield expr
        return

    placeholders = [Symbol(f"_canon{i}", real=True) for i in range(len(symbols))]
    yield _rename(expr, dict(zip(symbols, placeholders)))

    if len(symbols) > 1 and len(symbols) <= limit:
        for permutation in itertools.permutations(range(len(symbols))):
            if list(permutation) == list(range(len(symbols))):
                continue
            mapping = {symbols[i]: placeholders[permutation[i]] for i in range(len(symbols))}
            yield _rename(expr, mapping)


